* {
  box-sizing:border-box}
body {
  margin:0}
button,input,textarea,select {
  font:inherit}
button {
  cursor:pointer}
button:disabled {
  cursor:not-allowed;
  opacity:.4}
:focus-visible {
  outline:2px solid var(--app-color-text-foreground-tertiary);
  outline-offset:2px}
.rail {
