  .quest-list { border-right: 0; border-bottom: 1px solid var(--color-border-subtle); padding: 0 0 16px; }
}

/* One interaction timing throughout the desktop. */
button, a, summary, input, textarea, select {
  transition: color var(--transition-duration-basic) var(--ease-out),
              background-color var(--transition-duration-basic) var(--ease-out),
              border-color var(--transition-duration-basic) var(--ease-out);
}
.message .message-meta, .code-toolbar button, .copy-btn, .event-line .actions {
  opacity: 0;
  transition: opacity var(--transition-duration-basic) var(--ease-basic);
}
.message:hover .message-meta, .message:focus-within .message-meta,
.code-block:hover .code-toolbar button, .code-block:focus-within .code-toolbar button,
.command-card:hover .copy-btn, .command-card:focus-within .copy-btn,
.event-line:hover .actions, .event-line:focus-within .actions,
.code-toolbar button:focus-visible, .copy-btn:focus-visible {
  opacity: 1;
}
[data-chevron] { transition: transform var(--transition-duration-basic) var(--ease-out); }
[aria-expanded="true"] > [data-chevron] { transform: rotate(90deg); }
.detail-collapsible {
  overflow: hidden;
  height: 0;
  opacity: 0;
  margin-inline-start: -8px;
  padding-inline-start: 8px;
  transition: height var(--transition-duration-basic) var(--ease-out),
              opacity var(--transition-duration-basic) var(--ease-out);
}
.event-group > .detail-collapsible > .event-detail { padding: 12px 0 0 24px; gap: 12px; }
.event-line > .detail-collapsible > .event-detail { padding: 8px 0 4px 24px; gap: 8px; }
.event-detail dt { flex:none; min-width:64px; }
