    teams: <><circle cx="9" cy="8" r="3" /><path d="M3.5 19c.3-3.2 2.1-5 5.5-5s5.2 1.8 5.5 5M15 5.5a3 3 0 0 1 0 5.8M16 14c2.5.3 3.9 2 4 5" /></>,
    memory: <><path d="M12 3.5 20.5 12 12 20.5 3.5 12z" /><circle cx="12" cy="12" r="2.5" /></>,
