import { useState, type ReactNode } from "react";

export type SettingId = "general" | "shortcuts" | "models" | "environment" |
  "storage" | "connections" | "maintenance";

export interface SettingItem {
  id: SettingId;
  label: string;
  description: string;
  accessibleLabel?: string;
  keywords?: string;
}
interface SettingGroup { label: string; items: SettingItem[] }

export const settingGroups: SettingGroup[] = [
  { label: "工作空间", items: [
    { id: "general", label: "工作空间概况", accessibleLabel: "常规", description: "查看当前工作空间、Router 模型与 Core 连接状态。", keywords: "目录 路径 状态" },
    { id: "shortcuts", label: "键盘快捷键", description: "查找发送消息、换行和打开设置的键盘操作。" },
  ] },
  { label: "模型与运行", items: [
    { id: "models", label: "模型库", description: "管理模型档案、协议支持、上下文上限与能力来源。", keywords: "Registry 供应商 能力测量 启用 禁用" },
    { id: "environment", label: "运行配置", accessibleLabel: "环境", description: "配置模型连接、Router、Token 上限及网络访问范围。", keywords: "供应商 地址 API 网络 白名单 并发 重启" },
    { id: "storage", label: "用量与预算", accessibleLabel: "存储", description: "查看 Token 预算、已确认用量、未结算预留与并发占用。", keywords: "费用 货币 消耗 账本" },
  ] },
  { label: "安全与数据", items: [
    { id: "connections", label: "供应商凭据", accessibleLabel: "连接", description: "在桌面应用的系统凭据库中保存、检查和删除供应商凭据。", keywords: "密钥 API key credential" },
    { id: "maintenance", label: "备份与恢复", description: "备份和恢复工作空间，检查维护状态与恢复后的写入锁定。", keywords: "维护 数据 回滚 Core 重启" },
  ] },
];

export const settingMetadata = Object.fromEntries(settingGroups.flatMap((group) => group.items).map((item) => [item.id, item])) as Record<SettingId, SettingItem>;

export function SettingsRow({ label, description, children }: { label: ReactNode; description?: ReactNode; children: ReactNode }) {
  return <div className="settings-row">
    <div className="settings-row-text"><div className="settings-row-label">{label}</div>{description && <div className="settings-row-desc">{description}</div>}</div>
    <div className="settings-row-control settings-row-value">{children}</div>
  </div>;
}

export default function SettingsView({ selected, onSelect, children }: { selected: SettingId; onSelect: (id: SettingId) => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.description} ${item.accessibleLabel || ""} ${item.keywords || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const current = settingMetadata[selected];
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <h1 className="settings-page-title">设置</h1><div className="settings-search"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" /><path d="m16 16 4 4" /></svg><input type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} /></div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onClick={() => onSelect(item.id)}><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <p className="notice">未找到匹配的设置</p>}
    </nav>
    <div className="settings-content"><div className="settings-content-inner"><h1 className="settings-title">{current.label}</h1><p className="settings-description">{current.description}</p>{children}</div></div>
  </section>;
}

import { invoke } from "@tauri-apps/api/core";
import { Children, isValidElement, useState, type ReactNode, type RefObject } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import AnimatedDetails from "./AnimatedDetails";
import { safeExternalUrl } from "./logic";
import { mergeTimeline, messageMetadata, type ChatMessage, type Outgoing, type TimelineEvent, type TimelineItem } from "./timeline";

type Row = Record<string, unknown>;
type Quest = { id: string; title: string; status: string; version: number };
const text = (value: unknown, fallback = "未知") => value == null || value === "" ? fallback : String(value);

function contentText(node: ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (isValidElement<{ children?: ReactNode }>(node)) return contentText(node.props.children);
  return Children.toArray(node).map(contentText).join("");
}

function MarkdownMessage({ content, native, onInspect }: { content: string; native: boolean; onInspect: () => void }) {
  const [status, setStatus] = useState("");
  const copy = async (value: string) => {
    onInspect();
    try { await navigator.clipboard.writeText(value); setStatus("已复制"); }
    catch { setStatus("无法复制，请手动选择代码。"); }
  };
  const link = (href: string | undefined, children: ReactNode) => {
    const safe = safeExternalUrl(href);
    if (!safe) return <span>{children}</span>;
    if (native) return <button type="button" className="markdown-link" onClick={() => { void invoke("open_external", { url: safe }).catch(() => setStatus("无法在系统浏览器中打开链接。")); }}>{children}</button>;
    return <a href={safe} target="_blank" rel="noopener noreferrer">{children}</a>;
  };
  return <div className="markdown"><ReactMarkdown skipHtml remarkPlugins={[remarkGfm]} components={{
    a({ href, children }) {
      return link(href, children);
    },
    img({ src, alt }) { return <span className="image-placeholder">图片未自动加载{alt ? `：${alt}` : ""}{safeExternalUrl(src) && <> · {link(src, "打开图片链接")}</>}</span>; },
    pre({ children }) { const code = contentText(children); return <div className="code-block"><div className="code-toolbar"><span>代码</span><button type="button" onClick={() => void copy(code)}>复制</button></div><pre>{children}</pre></div>; },
  }}>{content}</ReactMarkdown>{status && <span className="copy-status" role="status">{status}</span>}</div>;
}

type DisplayItem = Exclude<TimelineItem, { type: "event" }> | { type: "group"; questId: string | null; events: TimelineEvent[] };
function eventTitle(event: TimelineEvent): string {
  const labels: Record<string, string> = { "quest.proposed": "创建了任务", "quest.status_changed": "任务状态已更新", "quest.plan_proposed": "提出了计划", "quest.plan_approved": "计划已批准", "team.proposed": "提出了团队", "team.approved": "团队已批准", "team.reassigned": "团队已调整", "team.revoked": "团队批准已撤销", "worker.proposed": "提出了 Worker", "worker.started": "Worker 已启动", "worker.blocked": "Worker 已阻塞", "worker.failed": "Worker 执行失败", "worker.result": "已记录 Worker 结果", "worker.retry": "Worker 正在重试", "worker.help_requested": "Worker 请求协助", "tool.intent_prepared": "已准备工具操作", "tool.receipt_recorded": "已记录工具回执", "tool.execution_uncertain": "工具结果未知", "approval.requested": "需要审批", "approval.decided": "审批已处理", "approval.revoked": "审批已撤销", "evidence.json_checked": "已检查 JSON 语法", "task.verified": "任务已验证" };
  if (event.kind === "context_archive") return "上下文已自动压缩";
  if (event.kind === "semantic_test") return event.status === "passed" ? "独立语义验证通过" : "独立语义验证";
  if (event.kind === "tool_receipt") {
    const detail = event.detail && typeof event.detail === "object" ? event.detail as Row : {};
    const tools: Record<string, string> = { file_read: "已读取文件", file_write: "编辑了文件", file_revise: "编辑了文件", shell_inspect: "运行了命令", python_compile: "运行了命令", git_status: "运行了命令", numeric_ast: "运行了命令", browser_get: "已搜索网页" };
    return tools[text(detail.tool, "")] || "调用了一个工具";
  }
  if (event.status === "worker.proposed" || event.status === "worker.started") return "已创建聊天";
  return labels[text(event.status, "")] || event.title;
}

function ActivityIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="2" /><path d="m8 10 2 2-2 2m4 0h4" /></svg>;
}

function Chevron() {
  return <svg data-chevron viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg>;
}

function CommandCard({ detail, onInspect }: { detail: Row; onInspect: () => void }) {
  const [copyStatus, setCopyStatus] = useState("");
  const command = text(detail.command, "");
  // The current Core normally returns a receipt digest, not stdout. Never infer output from it.
  const output = [detail.stdout, detail.output, detail.stderr].filter((value): value is string => typeof value === "string").join("\n");
  const copy = async () => {
    onInspect();
    try { await navigator.clipboard.writeText(command); setCopyStatus("已复制"); }
    catch { setCopyStatus("无法复制，请手动选择代码。"); }
  };
  return <div className="command-card"><header>{detail.tool === "shell_inspect" ? "Shell" : text(detail.tool, "Shell")}</header>
    <div className="command-line"><div className="cmd">{command}</div><button type="button" className="copy-btn" aria-label="复制" onClick={() => void copy()}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="5.5" y="5.5" width="8" height="8" rx="1.5" /><path d="M10.5 5.5v-2a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2" /></svg></button></div>
    {output ? <div className="out vertical-scroll-fade-mask"><code>{output}</code></div> : <p className="command-no-output">暂无输出</p>}
    {copyStatus && <span className="copy-status" role="status">{copyStatus}</span>}
  </div>;
}

function EventLine({ event, onQuest, onInspect }: { event: TimelineEvent; onQuest: (id: string) => void; onInspect: () => void }) {
  const detail = event.detail && typeof event.detail === "object" && !Array.isArray(event.detail) ? event.detail as Row : {};
  const target = typeof detail.path === "string" ? detail.path : typeof detail.command === "string" ? detail.command : "";
  const failed = event.status === "failed" || event.status === "worker.failed" || event.status === "tool.execution_uncertain" || (typeof detail.exit_code === "number" && detail.exit_code !== 0);
  const unknown = event.status === "unknown" || event.status === "uncertain" || event.status === "tool.execution_uncertain";
  return <AnimatedDetails onInspect={onInspect} className={`event-line${failed ? " failed" : ""}${unknown ? " unknown" : ""}`} summary={<><ActivityIcon /><span className="event-label">{target || eventTitle(event)}{(failed || unknown) && <span className="event-failed"> · {unknown ? "结果未知" : "失败"}{typeof detail.exit_code === "number" ? `（退出码 ${detail.exit_code}）` : ""}</span>}{event.execution_mode === "mock" && <small className="event-mode"> · 模拟</small>}</span><Chevron /></>}>
    <div className="event-detail">
      {typeof detail.command === "string" && <CommandCard detail={detail} onInspect={onInspect} />}
      {["file_write", "file_revise"].includes(text(detail.tool, "")) && typeof detail.path === "string" && <div className="resource-card"><span className="resource-icon" aria-hidden="true"><ActivityIcon /></span><span><strong>{detail.path}</strong><small>{eventTitle(event)}</small></span></div>}
      <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>{event.quest_id && <button className="text-button" onClick={() => onQuest(event.quest_id!)}>查看关联任务</button>}<dl>{Object.entries(detail).filter(([key]) => !(typeof detail.command === "string" && ["stdout", "output", "stderr"].includes(key))).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数" } as Record<string, string>)[key] || key}</dt><dd>{text(value)}</dd></div>)}</dl><small>记录 ID：{event.event_id}</small>
    </div></AnimatedDetails>;
}

function EventGroup({ item, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; onQuest: (id: string) => void; onInspect: () => void }) {
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  return <AnimatedDetails className="event-group" onInspect={onInspect} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon /><span className="event-label">{summary}</span><Chevron /></>}>
    <div className="event-detail">{item.events.map((event) => <EventLine key={`${event.kind}:${event.event_id}`} event={event} onQuest={onQuest} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}
function groupEvents(items: TimelineItem[]): DisplayItem[] {
  const grouped: DisplayItem[] = [];
  for (const item of items) {
    if (item.type !== "event") { grouped.push(item); continue; }
    const last = grouped[grouped.length - 1], questId = item.value.quest_id || null;
    if (last?.type === "group" && last.questId === questId) last.events.push(item.value);
    else grouped.push({ type: "group", questId, events: [item.value] });
  }
  return grouped;
}

export default function ChatTimeline({ messages, events, outgoing, quests, approvals, native,
  connected, historyMore, historyBusy, timelineError, conversationError, approvalError,
  canRetry, scrollRef, onScroll, onInspect, onLoadOlder, onRetry, onQuest, onApproval, approvalsBlocked, onApprovalDecision }: {
  messages: ChatMessage[]; events: TimelineEvent[]; outgoing: Outgoing[]; quests: Quest[]; approvals: Row[];
  native: boolean; connected: boolean; historyMore: boolean; historyBusy: boolean; timelineError: string;
  conversationError: string; approvalError: string; canRetry: boolean; scrollRef: RefObject<HTMLDivElement>;
  onScroll: () => void; onInspect: () => void; onLoadOlder: () => void; onRetry: (item: Outgoing) => void;
  onQuest: (id: string) => void; onApproval: (id: string) => void;
  approvalsBlocked: boolean; onApprovalDecision: (item: Row, decision: "APPROVED" | "REJECTED") => void;
}) {
  const items = groupEvents(mergeTimeline(messages, events, outgoing));
  const active = quests.filter((quest) => !["completed", "cancelled", "failed", "rejected"].includes(quest.status)).slice(0, 3);
  return <div className="timeline" ref={scrollRef} onScroll={onScroll} onMouseUp={() => { if (window.getSelection()?.toString()) onInspect(); }} aria-label="对话历史">
    {historyMore && <button className="text-button history" disabled={historyBusy} onClick={onLoadOlder}>{historyBusy ? "正在加载…" : "加载更早的消息与记录"}</button>}
    {conversationError && <p className="notice error" role="alert">{conversationError}</p>}
    {timelineError && <p className="notice error" role="alert">过程记录暂不可用：{timelineError}</p>}
    {!items.length && <div className="empty-conversation"><svg className="empty-symbol" viewBox="149 149 418 418" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M247.429 247.43C257.73 208.911 292.871 180.543 334.638 180.543C359.555 180.543 382.115 190.64 398.449 206.964C405.906 204.97 413.743 203.905 421.829 203.905C471.681 203.906 512.096 244.32 512.096 294.173C512.096 302.259 511.031 310.096 509.037 317.553C525.361 333.887 535.458 356.446 535.458 381.364C535.458 423.131 507.09 458.271 468.571 468.572C458.271 507.091 423.131 535.459 381.364 535.459C356.446 535.459 333.886 525.362 317.552 509.037C310.095 511.031 302.258 512.097 294.172 512.097C244.319 512.097 203.906 471.682 203.906 421.829C203.906 413.743 204.969 405.905 206.963 398.448C190.639 382.115 180.543 359.555 180.543 334.638C180.543 292.871 208.91 257.73 247.429 247.43Z" strokeWidth="41.162" /><path d="M436.706 408.738H370.021M276.533 309.154L303.468 357.831C304.433 359.575 304.412 361.698 303.414 363.423L276.533 409.854" strokeWidth="24" /></svg><h2>你想让我们在 FORGE 中构建什么？</h2><p>从这里开始。描述目标，或继续之前的任务。所有结果都会回到这个对话。</p></div>}
    {items.map((item) => {
      if (item.type === "group") return <EventGroup key={`${item.events[0].kind}:${item.events[0].event_id}`} item={item} onQuest={onQuest} onInspect={onInspect} />;
      if (item.type === "outgoing") return <article key={`outgoing:${item.value.requestId}`} className="message from-user"><div className="message-meta"><span className="message-avatar">你</span><strong>你</strong><span>{item.value.status === "sending" ? "发送中" : "发送失败"}</span></div><div className="message-body"><MarkdownMessage content={item.value.content} native={native} onInspect={onInspect} />{item.value.status === "failed" && <div className="outgoing-error" role="alert">{item.value.error || "请求未完成"} · 请求 ID：<code>{item.value.requestId}</code><button className="text-button" disabled={!canRetry} onClick={() => onRetry(item.value)}>使用原请求重试</button></div>}</div></article>;
      const message = item.value, meta = messageMetadata(message.metadata);
      return <article key={message.id} className={`message ${message.role === "user" ? "from-user" : "from-agent"}`}><div className="message-meta"><span className="message-avatar">{message.role === "user" ? "你" : "F"}</span><strong>{message.role === "user" ? "你" : "FORGE"}</strong>{meta.execution_mode === "mock" && <span>模拟</span>}{meta.execution_mode === "live" && <span>真实执行</span>}{message.role !== "user" && meta.execution_mode !== "live" && meta.execution_mode !== "mock" && <span>来源未知</span>}<time>{message.created_at ? new Date(message.created_at).toLocaleString() : ""}</time></div><div className="message-body"><MarkdownMessage content={message.content} native={native} onInspect={onInspect} /></div></article>;
    })}
    {connected && (active.length > 0 || approvals.length > 0) && <section className="timeline-updates" aria-label="任务与审批更新"><div className="timeline-updates-label">当前任务与审批</div>{approvals.slice(0, 3).map((item) => <div className="timeline-update approval-card" key={text(item.id)}><button className="approval-summary" onClick={() => onApproval(text(item.quest_id, ""))}><span><strong>需要审批 · {text(item.action_type)}</strong><small>风险 {text(item.risk)} · {text(item.resource_scope)}</small></span><span aria-hidden="true">›</span></button><dl><dt>计划版本</dt><dd>{text(item.plan_revision)}</dd><dt>参数摘要</dt><dd className="mono break">{text(item.parameter_digest)}</dd><dt>原因</dt><dd>{text(item.reason)}</dd><dt>过期时间</dt><dd>{text(item.expires_at)}</dd></dl><div className="button-row">{(["APPROVED", "REJECTED"] as const).map((decision) => <button key={decision} className={decision === "APPROVED" ? "button primary" : "button"} disabled={approvalsBlocked || typeof item.parameter_digest !== "string" || typeof item.plan_revision !== "number"} onClick={() => onApprovalDecision(item, decision)}>{decision === "APPROVED" ? "批准" : "拒绝"}</button>)}</div></div>)}{active.map((quest) => <button className="timeline-update" key={quest.id} onClick={() => onQuest(quest.id)}><span><strong>{quest.title}</strong><small>状态：{quest.status} · 版本 {quest.version}</small></span><span aria-hidden="true">›</span></button>)}</section>}
    {connected && approvalError && <p className="notice error" role="alert">审批状态暂不可用：{approvalError}</p>}
  </div>;
}

// Test-only HTTP fixtures; no live provider, workspace or credentials are used.
async (page) => {
  const sent = [];
  let posted = 0;
  let releaseFirst;
  let firstArrived;
  const firstRequest = new Promise((resolve) => { firstArrived = resolve; });
  let saved = Array.from({ length: 20 }, (_, index) => ({ id: `history-${index}`, role: 'assistant', content: `Synthetic historical message ${index}`, created_at: `2025-01-01T00:00:${String(index).padStart(2, '0')}Z`, metadata: { execution_mode: 'mock' } }));
  let externalRequests = 0;
  await page.route('https://tracker.invalid/**', async (route) => { externalRequests += 1; await route.abort(); });
  await page.route('http://127.0.0.1:8765/**', async (route) => {
    const req = route.request();
    const url = new URL(req.url());
    const headers = { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*', 'access-control-allow-methods': 'GET,POST,OPTIONS' };
    if (req.method() === 'OPTIONS') return route.fulfill({ status: 204, headers });
    let body = {};
    let status = 200;
    if (url.pathname === '/health') body = { session: 'test-session' };
    else if (url.pathname === '/api/conversation/message') {
      sent.push(JSON.parse(req.postData() || '{}'));
      posted += 1;
      if (posted === 1) { await new Promise((resolve) => { releaseFirst = resolve; firstArrived(); }); status = 409; body = { detail: 'test conflict' }; }
      else {
        const user_message = { id: 'm1', role: 'user', content: sent.at(-1).content, created_at: '2026-01-01T00:00:01Z', metadata: { request_id: sent.at(-1).request_id } };
        const assistant_message = { id: 'm2', role: 'assistant', content: '```python\nprint(1)\n```\n![tracker](https://tracker.invalid/pixel?token=synthetic)\n<script>window.bad=true</script>\n[unsafe](javascript:alert(1))', created_at: '2026-01-01T00:00:03Z', metadata: { execution_mode: 'mock' } };
        saved = [...saved, user_message, assistant_message]; body = { intent: 'chat', user_message, assistant_message };
      }
    } else if (url.pathname === '/api/conversation') body = { messages: saved, next_before: null, has_more: false };
    else if (url.pathname === '/api/quests') body = { items: [], next_before: null, has_more: false };
    else if (url.pathname === '/api/approvals/pending') body = { items: [], next_before: null, has_more: false };
    else if (url.pathname === '/api/activity') body = { items: [], next_before: null, has_more: false };
    else if (url.pathname === '/api/memory') body = { items: [], cursor: null, omitted: 0, bytes: 0 };
    else if (url.pathname === '/api/timeline') body = { items: [{ kind: 'tool_receipt', event_id: 'receipt-1', seq: null, created_at: '2026-01-01T00:00:02Z', quest_id: null, title: 'Tool execution recorded', status: 'succeeded', detail: { tool: 'file_read', path: 'input.txt', result_sha256: 'a'.repeat(64) }, execution_mode: 'mock' }], next_before: null, has_more: false };
    else if (url.pathname === '/api/models') body = [];
    else if (url.pathname === '/api/settings') body = { revision: 0, config: null, context_limit: 8192, restore_fenced: false, environment_overrides: [] };
    else if (url.pathname === '/api/budget') body = { token_limit: 0, concurrency_limit: 1 };
    else { status = 404; body = { detail: 'fixture endpoint missing' }; }
    await route.fulfill({ status, headers, contentType: 'application/json', body: JSON.stringify(body) });
  });
  await page.goto('http://127.0.0.1:5173/');
  await page.getByLabel('Core 启动密钥').fill('ab'.repeat(32));
  await page.getByRole('button', { name: '连接', exact: true }).click();
  await page.getByText('Core 已连接', { exact: true }).first().waitFor();
  const draft = page.getByLabel('消息内容');
  await draft.fill('synthetic draft');
  await page.getByRole('button', { name: '发送消息' }).click();
  await page.getByText('发送中', { exact: true }).waitFor();
  await firstRequest;
  await draft.fill('next draft');
  releaseFirst();
  await page.getByText(/test conflict/).first().waitFor();
  if (await draft.inputValue() !== 'next draft') throw new Error('failed send overwrote next draft');
  await page.getByRole('button', { name: '使用原请求重试' }).click();
  await page.getByRole('button', { name: '使用原请求重试' }).waitFor({ state: 'detached' });
  if (await draft.inputValue() !== 'next draft') throw new Error('retry lost next draft');
  if (sent.length !== 2 || sent[0].request_id !== sent[1].request_id) throw new Error('retry changed request ID');
  await draft.evaluate((element) => element.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', isComposing: true, bubbles: true })));
  await page.waitForTimeout(100);
  if (sent.length !== 2 || await draft.inputValue() !== 'next draft') throw new Error('IME composition submitted a message');
  const activity = page.locator('.event-group > summary').filter({ hasText: '已读取文件' });
  await activity.waitFor();
  await activity.scrollIntoViewIfNeeded();
  await activity.click();
  await page.locator('.event-line > summary').filter({ hasText: 'input.txt' }).click();
  await page.getByText('结果摘要').waitFor();
  const timeline = page.getByLabel('对话历史');
  const position = await timeline.evaluate((element) => element.scrollTop);
  await page.waitForTimeout(12500);
  const afterPolls = await timeline.evaluate((element) => element.scrollTop);
  if (Math.abs(position - afterPolls) > 1) throw new Error('polling moved an expanded record');
  await page.getByRole('button', { name: '复制', exact: true }).waitFor();
  await page.context().grantPermissions(['clipboard-read', 'clipboard-write'], { origin: 'http://127.0.0.1:5173' });
  await page.getByRole('button', { name: '复制', exact: true }).click();
  if (!(await page.evaluate(() => navigator.clipboard.readText())).includes('print(1)')) throw new Error('code copy did not copy the code');
  if (await page.locator('.markdown img, .markdown script, .markdown a[href^="javascript:"]').count()) throw new Error('unsafe Markdown content rendered');
  if (externalRequests || await page.evaluate(() => window.bad === true)) throw new Error('untrusted Markdown executed or loaded an external image');
  for (const label of ['后台任务','运行活动','模型库','任务团队','记忆中心','审批中心','设置','对话']) {
    if (label === '模型库') await page.keyboard.press('Control+,');
    const destination = ['模型库','任务团队','记忆中心','审批中心'].includes(label)
      ? page.locator('.settings-nav').getByRole('button', { name: label, exact: true })
      : page.getByRole('button', { name: label, exact: true });
    await destination.click();
    if (await page.locator('textarea[aria-label="消息内容"]').count() !== 1) throw new Error(`chat missing in ${label}`);
  }
  const storage = await page.evaluate(() => ({ local: localStorage.length, session: sessionStorage.length }));
  if (storage.local || storage.session) throw new Error('unexpected persistent browser storage');
  return { status: 'passed', requests: sent.length, requestIdReused: true, singleChat: true, storage };
}

