  const near = (value, expected, message, tolerance = 1) => check(Math.abs(value - expected) <= tolerance, `${message}: ${value} (expected ${expected})`);
  const box = async (locator) => { const value = await locator.boundingBox(); if (!value) throw new Error('expected a visible element'); return value; };
  const style = (locator, property) => locator.evaluate((element, key) => getComputedStyle(element).getPropertyValue(key), property);
  const shots = [];
  const screenshot = async (name) => {
    // Routing may put a different row under the previous pointer position.
