import { isClosedQuest, needsQuestAttention, statusLabel } from "./presentation";

export interface WorkspaceSidebarProps {
  connected: boolean;
  workspaceId: string;
  workspaceRoot: string;
  quests: Array<{ id: string; title: string; status: string }>;
  selectedId: string;
  chatActive: boolean;
  ready: boolean;
  questError: string;
  approvalError: string;
  pendingApprovals: number;
  onChat: () => void;
  onQuest: (id: string) => void;
  onTasks: () => void;
  onApprovals: () => void;
  children: ReactNode;
}

export default function WorkspaceSidebar({
  connected, workspaceId, workspaceRoot, quests, selectedId, chatActive, ready,
  questError, approvalError, pendingApprovals, onChat, onQuest, onTasks,
  onApprovals, children,
}: WorkspaceSidebarProps) {
